SELECT id, customer_id, plan, start_date, end_date, monthly_fee, LEAD(monthly_fee, 1) OVER (ORDER BY end_date, id) next_monthly_fee, LAST_VALUE(monthly_fee, TRUE) OVER (ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_monthly_fee, DENSE_RANK() OVER (ORDER BY monthly_fee DESC) monthly_fee_dense_rank, ROW_NUMBER() OVER w_recent seq_no FROM subscriptions WINDOW w_recent AS (ORDER BY start_date DESC, id);
